'use strict';

// Exercises the shipped offline instrument and actual Chromium Web Audio.
// Signals generated here are test fixtures; BATTER's factory sound is recorded audio.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const os = require('node:os');
const http = require('node:http');
const { pathToFileURL } = require('node:url');
const { chromium } = require(process.env.PLAYWRIGHT_MODULE || 'playwright');
const source = __dirname, root = path.resolve(source, '..');
const artifacts = process.env.BATTER_QA_ARTIFACTS || path.join(os.tmpdir(), 'batter-browser-qa');
const passed = [], measurements = [], skipped = [];
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

async function serve() {
  const server = http.createServer((request, response) => {
    const pathname = decodeURIComponent(new URL(request.url, 'http://localhost').pathname);
    const base=pathname.startsWith('/batter/')?source:root,relative=pathname.startsWith('/batter/')?pathname.slice(7):pathname;
    const file = path.resolve(base, '.' + relative + (pathname.endsWith('/') ? 'index.html' : ''));
    if (!file.startsWith(base + path.sep)) { response.writeHead(403); response.end(); return; }
    fs.readFile(file, (error, bytes) => {
      if (error) { response.writeHead(404); response.end(); return; }
      const mime = { '.html':'text/html', '.json':'application/json', '.css':'text/css', '.js':'application/javascript', '.wav':'audio/wav' }[path.extname(file)] || 'application/octet-stream';
      response.writeHead(200, { 'Content-Type':mime, 'Content-Length':bytes.length, 'Cache-Control':'no-store' }); response.end(bytes);
    });
  });
  await new Promise((resolve, reject) => { server.once('error', reject); server.listen(0, '127.0.0.1', resolve); });
  return { url:'http://127.0.0.1:' + server.address().port, close:() => new Promise(resolve => server.close(resolve)) };
}

async function prepareOffline(page, serverURL) {
  try { await prepare(page,pathToFileURL(path.join(source,'index.html')).href); measurements.push({offlineMode:'literal file URL'}); }
  catch(error) {
    if(!/ERR_BLOCKED_BY_ADMINISTRATOR/.test(error.message))throw error;
    await page.route('**/*', route => route.request().isNavigationRequest() ? route.fulfill({status:200,contentType:'text/html',body:fs.readFileSync(path.join(source,'index.html'))}) : route.abort('internetdisconnected'));
    await prepare(page,serverURL+'/batter/index.html');measurements.push({offlineMode:'managed Chromium blocks file URLs; exact standalone HTML fulfilled with every external request disabled'});
  }
}

async function prepare(page, url) {
  await page.goto(url, { waitUntil:'load' });
  await page.waitForFunction(() => !!window.BatterUI?.engine && !!window.BatterSchema, null, { timeout:30000 });
  await page.evaluate(() => {
    window.qa = {
      engine:window.BatterUI.engine,
      state:() => window.BatterUI.engine.getState(),
      set:state => { window.BatterUI.engine.setState(state); window.BatterUI.refresh(); },
      clean:() => { const state=window.BatterUI.engine.getState(); state.tempo=240; state.swing=0; state.humanize=0; state.velocityHumanize=0; state.master.volume=1; state.lanes.forEach(l=>{l.room=0;l.delay=0;l.mute=false;l.solo=false;l.volume=.9;l.layerMode='single';}); return state; },
      audio:async blob => { const bytes=await blob.arrayBuffer(),view=new DataView(bytes),frames=(bytes.byteLength-44)/4,left=new Float32Array(frames),right=new Float32Array(frames); for(let i=0;i<frames;i++){left[i]=view.getInt16(44+i*4,true)/32768;right[i]=view.getInt16(46+i*4,true)/32768;} return {left,right,rate:view.getUint32(24,true),frames,bytes:bytes.byteLength,header:String.fromCharCode(...new Uint8Array(bytes,0,4)),dataBytes:view.getUint32(40,true),channels:view.getUint16(22,true)}; },
      stats:audio => { let sumL=0,sumR=0,peak=0,last=-1,finite=true; for(let i=0;i<audio.frames;i++){const l=audio.left[i],r=audio.right[i];sumL+=l*l;sumR+=r*r;peak=Math.max(peak,Math.abs(l),Math.abs(r));finite=finite&&Number.isFinite(l)&&Number.isFinite(r);if(Math.abs(l)+Math.abs(r)>1/32768)last=i;}return {rmsL:Math.sqrt(sumL/audio.frames),rmsR:Math.sqrt(sumR/audio.frames),peak,last,finite,rate:audio.rate,frames:audio.frames,bytes:audio.bytes,header:audio.header,dataBytes:audio.dataBytes,channels:audio.channels}; },
      difference:(a,b) => { let delta=0,reference=0;for(let i=0;i<Math.min(a.frames,b.frames);i++){delta+=(a.left[i]-b.left[i])**2+(a.right[i]-b.right[i])**2;reference+=a.left[i]**2+a.right[i]**2;}return Math.sqrt(delta/Math.max(1e-12,reference)); },
      projection:(audio,frequency,channel='left',start=0,end=audio.frames/audio.rate) => { const samples=audio[channel],a=Math.floor(start*audio.rate),b=Math.min(audio.frames,Math.floor(end*audio.rate));let re=0,im=0;for(let i=a;i<b;i++){re+=samples[i]*Math.cos(2*Math.PI*frequency*i/audio.rate);im+=samples[i]*Math.sin(2*Math.PI*frequency*i/audio.rate);}return 2*Math.hypot(re,im)/Math.max(1,b-a); },
      energy:(audio,start,end) => { let sum=0;const a=Math.floor(start*audio.rate),b=Math.min(audio.frames,Math.floor(end*audio.rate));for(let i=a;i<b;i++)sum+=audio.left[i]**2+audio.right[i]**2;return Math.sqrt(sum/Math.max(1,(b-a)*2)); },
      fixture:(seconds=.2,rate=22050) => { const frames=Math.round(seconds*rate),left=new Float32Array(frames),right=new Float32Array(frames);for(let i=0;i<frames;i++){left[i]=.4*Math.sin(2*Math.PI*330*i/rate)*Math.exp(-i/rate*8);right[i]=.3*Math.sin(2*Math.PI*550*i/rate)*Math.exp(-i/rate*8);}return window.BatterSchema.wav({left,right,sampleRate:rate}); }
    };
  });
}

