    await page.evaluate(()=>window.BatterUI.refresh());await page.locator('#sampleBrowserButton').click();const button=page.locator('.library-card').filter({hasText:online.name});const downloadPromise=page.waitForEvent('download');await button.getByRole('link',{name:'Download bundle',exact:true}).click();const download=await downloadPromise,bundlePath=path.join(artifacts,'downloaded-acoustic-bundle.json');await download.saveAs(bundlePath);const data=JSON.parse(fs.readFileSync(bundlePath,'utf8'));assert(data.samples.length>=100&&data.samples.every(s=>s.base64&&s.license&&s.source));await page.locator('#closeSampleDialog').click();
    const offline=await browser.newPage();try{await prepareOffline(offline,url);await offline.setInputFiles('#bundleFile',bundlePath);await offline.waitForFunction(()=>document.getElementById('toast').textContent==='Sample bundle opened.');await offline.waitForFunction(()=>/kept.*browser|saved.*device|saved.*browser/i.test(document.getElementById('saveStatus').textContent),null,{timeout:15000});const packedBefore=await offline.evaluate(()=>window.qa.engine.getState({portable:'external'}));await prepare(offline,url+'/batter/index.html');assert.deepEqual(await offline.evaluate(()=>window.qa.engine.getState({portable:'external'})),packedBefore,'Offline-imported expanded samples survive closing and reopening the HTML without network.');const imported=await offline.evaluate(id=>window.qa.engine.getCatalog().kits.some(k=>k.id===id),online.id);assert(imported);assert.equal(await offline.evaluate(()=>window.qa.state().kitId),online.id);await offline.locator('#playButton').click();await offline.waitForFunction(()=>window.qa.engine.playing);await sleep(500);assert((await offline.evaluate(()=>window.qa.engine.getMeters().peak))>.001);passed.push('Real online bundle Download / offline file import / expanded kit remains playable without fetch');}finally{await offline.evaluate(()=>window.qa?.engine.dispose()).catch(()=>{});await offline.close();}
