    assert.match(exact.replaceError,/Confirm|replace/i);assert.match(exact.mapError,/destination|voice|drum/i);assert(exact.same);for(let i=0;i<exact.packet.notes.length;i++){const a=exact.packet.notes[i],b=exact.captured.notes[i];for(const key of ['beat','duration','velocity','probability','pitch'])assert.equal(b[key],a[key],'Shared rhythm preserves exact '+key);assert.equal(b.voice,'snare');}assert(exact.score.some(e=>Math.abs(e.beat-.127123)<1e-12));assert(exact.first>=Math.floor(.127123*.25*48000)&&exact.first<Math.ceil(.127123*.25*48000)+100);assert(exact.stats.rmsL>.001);passed.push('Shared pattern explicit mapping/replacement / exact off-grid beat, duration, pitch, velocity and chance / real timed audio / invalid mapping atomic');
    const audio=await page.evaluate(async()=>{const q=window.qa,app=window.BatterApp,shared=window.MusicLabExchange,originalSample=q.state().lanes[8].sampleId,frames=2205,pcm=new Float32Array(frames*2);for(let i=0;i<frames;i++){pcm[i*2]=.2*Math.sin(i*.12);pcm[i*2+1]=.13*Math.cos(i*.21);}const packet=shared.packetFromAudio({pcm,sampleRate:22050,name:'Cross-app acoustic ingredient',sourceApp:'spool'}),decoded=shared.audioFromPacket(packet);const interleaved=new Float32Array(frames*2);for(let i=0;i<frames;i++){interleaved[i*2]=decoded.pcm[0][i];interleaved[i*2+1]=decoded.pcm[1][i];}let guarded;try{await app.importAudio({pcm:interleaved,sampleRate:22050,name:packet.name,options:{target:'tomMid'}});}catch(error){guarded=error.message;}await app.importAudio({pcm:interleaved,sampleRate:22050,name:packet.name,options:{target:'tomMid',replace:true}});const source=await app.exportAudio({scope:'source',laneId:'tomMid'}),saved=await shared.save({...source,sourceApp:'batter'}),read=await shared.get(saved.id);let difference=0;for(let i=0;i<frames;i++){difference=Math.max(difference,Math.abs(source.pcm[i*2]-interleaved[i*2]),Math.abs(source.pcm[i*2+1]-interleaved[i*2+1]),Math.abs(read.pcm[0][i]-source.pcm[i*2]),Math.abs(read.pcm[1][i]-source.pcm[i*2+1]));}return {guarded,originalSample,rate:source.sampleRate,frames:source.pcm.length/2,difference,saved:saved.name,targets:app.audioImport.targets.length};});
    assert.match(audio.guarded,/Confirm|replace/i);assert.equal(audio.rate,22050);assert.equal(audio.frames,2205);assert(audio.difference<=2/32768);assert.equal(audio.targets,24);assert.equal(audio.saved,'Cross-app acoustic ingredient');passed.push('Actual shared sample packet / explicit lane replacement / stereo and original-rate source export / IndexedDB shared cupboard roundtrip');
    await page.locator('#undoButton').click();assert.equal(await page.evaluate(()=>window.qa.state().lanes[8].sampleId),audio.originalSample);await page.locator('#redoButton').click();assert.equal(await page.evaluate(()=>window.qa.engine.metadata.get(window.qa.state().lanes[8].sampleId).name),'Cross-app acoustic ingredient');
